using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

/// <summary>
/// Shared evaluation configuration wiring telemetry, quality, and compare modes.
/// </summary>
internal static class EvalConfig
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    /// <summary>
    /// Creates a <see cref="ReportingConfiguration"/> with quality evaluators
    /// and disk-based result storage (supports compare across runs).
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(IChatClient judgeChatClient)
    {
        // Quality evaluators
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var storage = new DiskBasedResultStorage(StoragePath);

        return new ReportingConfiguration(
            storage,
            judgeChatClient,
            evaluators);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that chat interactions produce observable telemetry
/// (token usage, response metadata) captured through the evaluation pipeline.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://localhost";

    private static readonly string Key =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "";

    [TestMethod]
    public async Task ChatCompletion_EmitsUsageTelemetry()
    {
        // Arrange
        IChatClient chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(Endpoint),
            new System.ClientModel.ApiKeyCredential(Key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Say hello in one word.")
        };

        // Act
        var response = await chatClient.GetResponseAsync(messages);

        // Assert – telemetry surfaces usage info
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0, "Expected at least one response message.");
        Assert.IsNotNull(response.Usage, "Expected usage telemetry to be present.");
        Assert.IsTrue(response.Usage.InputTokenCount > 0, "Expected non-zero input token count.");
        Assert.IsTrue(response.Usage.OutputTokenCount > 0, "Expected non-zero output token count.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: uses LLM-as-judge evaluators (coherence, relevance, fluency,
/// groundedness) to score chat responses and persist results for reporting.
/// </summary>
[TestClass]
public class QualityTests
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://localhost";

    private static readonly string Key =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "";

    private static IChatClient CreateChatClient() =>
        new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(Endpoint),
            new System.ClientModel.ApiKeyCredential(Key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThresholds()
    {
        // Arrange
        IChatClient chatClient = CreateChatClient();
        var reportingConfig = EvalConfig.CreateReportingConfig(chatClient);

        var scenario = new ScenarioRun("CoachGreeting", reportingConfig);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How do I stay motivated when learning something new?")
        };

        // Act
        var response = await chatClient.GetResponseAsync(messages);
        var modelResponse = response.Messages.Last();

        await scenario.EvaluateAsync(
            messages,
            modelResponse);

        await scenario.DisposeAsync();

        // Assert – all quality metrics should score above baseline (3/5)
        foreach (var result in scenario.EvaluationResults)
        {
            if (result.Value is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"{result.Key} scored {numeric.Value}, expected >= 3.");
            }
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same scenario against two prompt variants and
/// persists both results so the reporting tool can diff scores across runs.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://localhost";

    private static readonly string Key =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "";

    private static IChatClient CreateChatClient() =>
        new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(Endpoint),
            new System.ClientModel.ApiKeyCredential(Key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

    [TestMethod]
    public async Task ComparePromptVariants_ProducesComparableResults()
    {
        IChatClient chatClient = CreateChatClient();
        var reportingConfig = EvalConfig.CreateReportingConfig(chatClient);

        string userQuery = "Give me a tip to improve my focus.";

        // Variant A: concise system prompt
        var variantAResult = await RunVariantAsync(
            reportingConfig,
            chatClient,
            scenarioName: "FocusTip_VariantA",
            systemPrompt: "You are a brief coach. Answer in one sentence.",
            userQuery);

        // Variant B: detailed system prompt
        var variantBResult = await RunVariantAsync(
            reportingConfig,
            chatClient,
            scenarioName: "FocusTip_VariantB",
            systemPrompt: "You are a thorough coaching assistant. Provide a detailed, actionable answer.",
            userQuery);

        // Both variants should produce valid scores; compare is done via the report.
        Assert.IsTrue(variantAResult.Count > 0, "Variant A should produce evaluation results.");
        Assert.IsTrue(variantBResult.Count > 0, "Variant B should produce evaluation results.");
    }

    private static async Task<IDictionary<string, EvaluationMetric>> RunVariantAsync(
        ReportingConfiguration reportingConfig,
        IChatClient chatClient,
        string scenarioName,
        string systemPrompt,
        string userQuery)
    {
        var scenario = new ScenarioRun(scenarioName, reportingConfig);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, systemPrompt),
            new(ChatRole.User, userQuery)
        };

        var response = await chatClient.GetResponseAsync(messages);
        var modelResponse = response.Messages.Last();

        await scenario.EvaluateAsync(messages, modelResponse);
        await scenario.DisposeAsync();

        return scenario.EvaluationResults;
    }
}

