using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: uses LLM-as-judge evaluators (coherence, relevance, fluency,
/// groundedness) to score chat responses and persist results for reporting.
/// </summary>
[TestClass]
public class QualityTests
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://localhost";

    private static readonly string Key =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "";

    private static IChatClient CreateChatClient() =>
        new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(Endpoint),
            new System.ClientModel.ApiKeyCredential(Key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThresholds()
    {
        // Arrange
        IChatClient chatClient = CreateChatClient();
        var reportingConfig = EvalConfig.CreateReportingConfig(chatClient);

        var scenario = new ScenarioRun("CoachGreeting", reportingConfig);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How do I stay motivated when learning something new?")
        };

        // Act
        var response = await chatClient.GetResponseAsync(messages);
        var modelResponse = response.Messages.Last();

        await scenario.EvaluateAsync(
            messages,
            modelResponse);

        await scenario.DisposeAsync();

        // Assert – all quality metrics should score above baseline (3/5)
        foreach (var result in scenario.EvaluationResults)
        {
            if (result.Value is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"{result.Key} scored {numeric.Value}, expected >= 3.");
            }
        }
    }
}

